def rle(s):
    if not s: return ""

    result = []
    current_char, count = s[0], 1

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char, count = char, 1

    result.append(f"{current_char}{count}")

    return "".join(result)

def to_roman(n):
    roman_map = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    result = []
    for value, symbol in roman_map:
        while n >= value:
            result.append(symbol)
            n -= value

    return "".join(result)

def balanced(s):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in "([{":
            stack.append(char)
        elif char in ")]}":
            if not stack or stack.pop() != pairs[char]:
                return False

    return len(stack) == 0

def to_base(n, b):
    if n == 0:
        return "0"

    digit_map = '0123456789abcdef'
    digits = []

    while n > 0:
        remainder = n % b
        digits.append(digit_map[remainder])
        n //= b

    return "".join(reversed(digits))
